app/components/productivity/focus-timer..content:
"use client"

import { useState, useEffect, useRef } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Badge } from "@/components/ui/badge"
import { Progress } from "@/components/ui/progress"
import { Slider } from "@/components/ui/slider"
import { 
  Play, 
  Pause, 
  RotateCcw, 
  Coffee, 
  Brain, 
  Settings, 
  Clock,
  Target,
  Zap,
  Timer
} from "lucide-react"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { addNotification } from "./notification-system"

interface TimerSession {
  type: 'focus' | 'short-break' | 'long-break'
  duration: number
  completed: boolean
  startTime?: Date
  endTime?: Date
}

interface TimerStats {
  focusSessionsToday: number
  totalFocusTimeToday: number
  currentStreak: number
  longestStreak: number
}

const timerPresets = {
  pomodoro: { focus: 25, shortBreak: 5, longBreak: 15 },
  extended: { focus: 45, shortBreak: 10, longBreak: 20 },
  sprint: { focus: 15, shortBreak: 3, longBreak: 10 },
  marathon: { focus: 90, shortBreak: 15, longBreak: 30 }
}

const motivationalMessages = [
  "You're in the zone! Keep going strong.",
  "Focus is your superpower. Use it wisely.",
  "Every minute of focus gets you closer to your goals.",
  "Deep work is where breakthroughs happen.",
  "Your future self will thank you for this focus session.",
  "Concentration is the key to economic results.",
  "The expert in anything was once a beginner who refused to give up.",
  "Success is the sum of small efforts repeated day in and day out."
]

export default function FocusTimer() {
  const [currentSession, setCurrentSession] = useState<TimerSession>({
    type: 'focus',
    duration: 25,
    completed: false
  })
  const [timeLeft, setTimeLeft] = useState(25 * 60) // 25 minutes in seconds
  const [isRunning, setIsRunning] = useState(false)
  const [sessionCount, setSessionCount] = useState(0)
  const [stats, setStats] = useState<TimerStats>({
    focusSessionsToday: 0,
    totalFocusTimeToday: 0,
    currentStreak: 0,
    longestStreak: 0
  })
  const [selectedPreset, setSelectedPreset] = useState<keyof typeof timerPresets>('pomodoro')
  const [showSettings, setShowSettings] = useState(false)
  const [customDuration, setCustomDuration] = useState([25])
  const [motivationalMessage, setMotivationalMessage] = useState(motivationalMessages[0])

  const intervalRef = useRef<NodeJS.Timeout | null>(null)

  // Load stats from localStorage on mount
  useEffect(() => {
    const today = new Date().toDateString()
    const savedStats = localStorage.getItem(`timer_stats_${today}`)
    if (savedStats) {
      setStats(JSON.parse(savedStats))
    }
  }, [])

  // Timer countdown logic
  useEffect(() => {
    if (isRunning && timeLeft > 0) {
      intervalRef.current = setInterval(() => {
        setTimeLeft(prev => {
          if (prev <= 1) {
            handleSessionComplete()
            return 0
          }
          return prev - 1
        })
      }, 1000)
    } else if (intervalRef.current) {
      clearInterval(intervalRef.current)
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
      }
    }
  }, [isRunning, timeLeft])

  // Update motivational message periodically
  useEffect(() => {
    if (isRunning) {
      const messageInterval = setInterval(() => {
        const randomMessage = motivationalMessages[Math.floor(Math.random() * motivationalMessages.length)]
        setMotivationalMessage(randomMessage)
      }, 60000) // Change message every minute during focus

      return () => clearInterval(messageInterval)
    }
  }, [isRunning])

  const handleSessionComplete = () => {
    setIsRunning(false)

    // Show in-app notification
    addNotification({
      title: "Focus Session Complete!",
      message: `Your ${currentSession.type === 'focus' ? 'focus session' : 'break'} is complete. ${currentSession.type === 'focus' ? 'Time for a break!' : 'Ready to focus again?'}`,
      type: 'success',
      duration: 10000,
      actions: currentSession.type === 'focus' ? [
        {
          label: 'Start Break',
          action: () => {
            const breakType = (sessionCount + 1) % 4 === 0 ? 'long-break' : 'short-break'
            const breakDuration = breakType === 'long-break' 
              ? timerPresets[selectedPreset].longBreak 
              : timerPresets[selectedPreset].shortBreak

            setCurrentSession({
              type: breakType,
              duration: breakDuration,
              completed: false
            })
            setTimeLeft(breakDuration * 60)
            setIsRunning(true)
          }
        }
      ] : [
        {
          label: 'Start Focus',
          action: () => {
            setCurrentSession({
              type: 'focus',
              duration: timerPresets[selectedPreset].focus,
              completed: false
            })
            setTimeLeft(timerPresets[selectedPreset].focus * 60)
            setIsRunning(true)
          }
        }
      ]
    })

    // Show browser notification if supported
    if ("Notification" in window && Notification.permission === "granted") {
      new Notification("Focus Timer", {
        body: `${currentSession.type === 'focus' ? 'Focus session' : 'Break'} completed!`,
        icon: "/favicon.ico"
      })
    }

    // Update stats
    if (currentSession.type === 'focus') {
      const today = new Date().toDateString()
      const newStats = {
        ...stats,
        focusSessionsToday: stats.focusSessionsToday + 1,
        totalFocusTimeToday: stats.totalFocusTimeToday + currentSession.duration,
        currentStreak: stats.currentStreak + 1,
        longestStreak: Math.max(stats.longestStreak, stats.currentStreak + 1)
      }
      setStats(newStats)
      localStorage.setItem(`timer_stats_${today}`, JSON.stringify(newStats))
    }

    // Auto-switch to break after focus session
    if (currentSession.type === 'focus') {
      const breakType = (sessionCount + 1) % 4 === 0 ? 'long-break' : 'short-break'
      const breakDuration = breakType === 'long-break' 
        ? timerPresets[selectedPreset].longBreak 
        : timerPresets[selectedPreset].shortBreak

      setCurrentSession({
        type: breakType,
        duration: breakDuration,
        completed: false
      })
      setTimeLeft(breakDuration * 60)
      setSessionCount(prev => prev + 1)
    }
  }

  const startTimer = () => {
    setIsRunning(true)
    setCurrentSession(prev => ({
      ...prev,
      startTime: new Date()
    }))

    // Request notification permission
    if ("Notification" in window && Notification.permission === "default") {
      Notification.requestPermission()
    }
  }

  const pauseTimer = () => {
    setIsRunning(false)
  }

  const resetTimer = () => {
    setIsRunning(false)
    setTimeLeft(currentSession.duration * 60)
  }

  const applyPreset = (presetName: keyof typeof timerPresets) => {
    const preset = timerPresets[presetName]
    setSelectedPreset(presetName)
    setCurrentSession({
      type: 'focus',
      duration: preset.focus,
      completed: false
    })
    setTimeLeft(preset.focus * 60)
    setIsRunning(false)
  }

  const applyCustomDuration = () => {
    const duration = customDuration[0]
    setCurrentSession({
      type: 'focus',
      duration: duration,
      completed: false
    })
    setTimeLeft(duration * 60)
    setIsRunning(false)
  }

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60)
    const secs = seconds % 60
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`
  }

  const getSessionIcon = () => {
    switch (currentSession.type) {
      case 'focus':
        return <Brain className="h-5 w-5" />
      case 'short-break':
        return <Coffee className="h-5 w-5" />
      case 'long-break':
        return <Target className="h-5 w-5" />
      default:
        return <Timer className="h-5 w-5" />
    }
  }

  const getSessionColor = () => {
    switch (currentSession.type) {
      case 'focus':
        return 'from-blue-500 to-purple-500'
      case 'short-break':
        return 'from-green-500 to-teal-500'
      case 'long-break':
        return 'from-orange-500 to-red-500'
      default:
        return 'from-gray-500 to-gray-600'
    }
  }

  const progressPercentage = ((currentSession.duration * 60 - timeLeft) / (currentSession.duration * 60)) * 100

  return (
    <Card className="w-full">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className={`p-2 bg-gradient-to-br ${getSessionColor()} rounded-lg text-white`}>
              {getSessionIcon()}
            </div>
            <CardTitle className="text-lg">Focus Timer</CardTitle>
            <Badge variant="secondary" className="capitalize">
              {currentSession.type.replace('-', ' ')}
            </Badge>
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setShowSettings(!showSettings)}
            className="gap-2"
          >
            <Settings className="h-4 w-4" />
            Settings
          </Button>
        </div>
      </CardHeader>

      <CardContent className="space-y-6">
        {/* Timer Display */}
        <div className="text-center space-y-4">
          <div className="text-6xl font-mono font-bold text-gray-900 dark:text-white">
            {formatTime(timeLeft)}
          </div>

          <Progress 
            value={progressPercentage} 
            className="w-full h-3"
          />

          {isRunning && currentSession.type === 'focus' && (
            <p className="text-sm text-gray-600 dark:text-gray-400 italic">
              {motivationalMessage}
            </p>
          )}
        </div>

        {/* Timer Controls */}
        <div className="flex items-center justify-center gap-4">
          {!isRunning ? (
            <Button onClick={startTimer} className="gap-2 px-8">
              <Play className="h-4 w-4" />
              Start
            </Button>
          ) : (
            <Button onClick={pauseTimer} variant="outline" className="gap-2 px-8">
              <Pause className="h-4 w-4" />
              Pause
            </Button>
          )}

          <Button onClick={resetTimer} variant="outline" className="gap-2">
            <RotateCcw className="h-4 w-4" />
            Reset
          </Button>
        </div>

        {/* Stats Display */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="text-center">
            <div className="text-2xl font-bold text-blue-600">{stats.focusSessionsToday}</div>
            <div className="text-xs text-gray-500">Sessions Today</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-green-600">{Math.floor(stats.totalFocusTimeToday / 60)}h</div>
            <div className="text-xs text-gray-500">Focus Time</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-purple-600">{stats.currentStreak}</div>
            <div className="text-xs text-gray-500">Current Streak</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-orange-600">{stats.longestStreak}</div>
            <div className="text-xs text-gray-500">Best Streak</div>
          </div>
        </div>

        {/* Settings Panel */}
        <Collapsible open={showSettings} onOpenChange={setShowSettings}>
          <CollapsibleContent className="space-y-4 pt-4 border-t">
            <div>
              <h4 className="font-semibold mb-3">Timer Presets</h4>
              <div className="grid grid-cols-2 gap-2">
                {Object.entries(timerPresets).map(([key, preset]) => (
                  <Button
                    key={key}
                    variant={selectedPreset === key ? "default" : "outline"}
                    size="sm"
                    onClick={() => applyPreset(key as keyof typeof timerPresets)}
                    className="capitalize"
                  >
                    {key}
                    <div className="text-xs ml-2">
                      {preset.focus}m
                    </div>
                  </Button>
                ))}
              </div>
            </div>

            <div>
              <h4 className="font-semibold mb-3">Custom Duration</h4>
              <div className="space-y-3">
                <Slider
                  value={customDuration}
                  onValueChange={setCustomDuration}
                  max={120}
                  min={5}
                  step={5}
                  className="w-full"
                />
                <div className="flex items-center justify-between">
                  <span className="text-sm text-gray-600">{customDuration[0]} minutes</span>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={applyCustomDuration}
                  >
                    Apply
                  </Button>
                </div>
              </div>
            </div>
          </CollapsibleContent>
        </Collapsible>
      </CardContent>
    </Card>
  )
}

components/ui/toggle.tsx.content:
"use client"

import * as React from "react"
import * as TogglePrimitive from "@radix-ui/react-toggle"
import { cva, type VariantProps } from "class-variance-authority"

import { cn } from "@/lib/utils"

const toggleVariants = cva(
  "inline-flex items-center justify-center rounded-md text-sm font-medium ring-offset-background transition-colors hover:bg-muted hover:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 data-[state=on]:bg-accent data-[state=on]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0 gap-2",
  {
    variants: {
      variant: {
        default: "bg-transparent",
        outline:
          "border border-input bg-transparent hover:bg-accent hover:text-accent-foreground",
      },
      size: {
        default: "h-10 px-3 min-w-10",
        sm: "h-9 px-2.5 min-w-9",
        lg: "h-11 px-5 min-w-11",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
)

const Toggle = React.forwardRef<
  React.ElementRef<typeof TogglePrimitive.Root>,
  React.ComponentPropsWithoutRef<typeof TogglePrimitive.Root> &
    VariantProps<typeof toggleVariants>
>(({ className, variant, size, ...props }, ref) => (
  <TogglePrimitive.Root
    ref={ref}
    className={cn(toggleVariants({ variant, size, className }))}
    {...props}
  />
))

Toggle.displayName = TogglePrimitive.Root.displayName

export { Toggle, toggleVariants }

app/components/profile-view.tsx.content:
"use client"

import { useState } from "react"
import { User, Mail, Edit, Save, X, Eye, EyeOff, Crown, AlertTriangle } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import { useAuth } from "../contexts/auth-context"
import { updateUserProfile, changePassword, resetPassword } from "../lib/auth"

export default function ProfileView() {
  const { user, userData, refreshUserData } = useAuth()

  // Debug: Check if user and userData are available
  if (!user) {
    return (
      <div className="text-center p-8">
        <p className="text-gray-600 dark:text-gray-400">No user found. Please log in.</p>
      </div>
    )
  }

  if (!userData) {
    return (
      <div className="text-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600 mx-auto mb-4"></div>
        <p className="text-gray-600 dark:text-gray-400">Loading profile data...</p>
        <p className="text-sm text-gray-500 mt-2">User: {user?.email}</p>
      </div>
    )
  }
  const [isEditing, setIsEditing] = useState(false)
  const [isChangingPassword, setIsChangingPassword] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState("")
  const [success, setSuccess] = useState("")
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)

  const [profileData, setProfileData] = useState({
    fullName: userData?.fullName || "",
    username: userData?.username || "",
  })

  const [passwordData, setPasswordData] = useState({
    newPassword: "",
    confirmPassword: "",
  })

  const handleProfileUpdate = async () => {
    if (!userData || !user) return

    if (!profileData.fullName.trim() || !profileData.username.trim()) {
      setError("Full name and username are required")
      return
    }

    if (profileData.username.length < 3) {
      setError("Username must be at least 3 characters long")
      return
    }

    setLoading(true)
    setError("")
    setSuccess("")

    try {
      await updateUserProfile(user.uid, {
        fullName: profileData.fullName,
        username: profileData.username,
      })

      await refreshUserData()
      setSuccess("Profile updated successfully!")
      setIsEditing(false)
    } catch (error: any) {
      setError(error.message || "Failed to update profile")
    } finally {
      setLoading(false)
    }
  }

  const handlePasswordChange = async () => {
    if (!passwordData.newPassword || !passwordData.confirmPassword) {
      setError("Please fill in all password fields")
      return
    }

    if (passwordData.newPassword !== passwordData.confirmPassword) {
      setError("Passwords do not match")
      return
    }

    setLoading(true)
    setError("")
    setSuccess("")

    try {
      await changePassword(passwordData.newPassword)
      setSuccess("Password changed successfully!")
      setIsChangingPassword(false)
      setPasswordData({ newPassword: "", confirmPassword: "" })
    } catch (error: any) {
      if (error.message.includes("requires-recent-login")) {
        setError("For security reasons, please use the 'Send Password Reset Email' option below to change your password.")
      } else {
        setError(error.message || "Failed to change password")
      }
    } finally {
      setLoading(false)
    }
  }

  const handlePasswordReset = async () => {
    if (!userData?.email) {
      setError("No email address found")
      return
    }

    setLoading(true)
    setError("")
    setSuccess("")

    try {
      await resetPassword(userData.email)
      setSuccess("Password reset email sent! Check your inbox and follow the instructions to reset your password.")
      setIsChangingPassword(false)
    } catch (error: any) {
      setError(error.message || "Failed to send password reset email")
    } finally {
      setLoading(false)
    }
  }

  const handleCancel = () => {
    setIsEditing(false)
    setIsChangingPassword(false)
    setProfileData({
      fullName: userData?.fullName || "",
      username: userData?.username || "",
    })
    setPasswordData({ newPassword: "", confirmPassword: "" })
    setError("")
    setSuccess("")
  }

  if (!userData) {
    return (
      <div className="flex items-center justify-center h-[calc(100vh-4rem)]">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600 dark:text-gray-400">Loading profile...</p>
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      <div>
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">Profile Settings</h1>
        <p className="text-gray-600 dark:text-gray-300">Manage your account information</p>
      </div>

      <div className="space-y-6">
        {/* Profile Information */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <User className="h-5 w-5" />
              Profile Information
              {userData.isPremium && (
                <Badge className="bg-gradient-to-r from-purple-500 to-blue-500 text-white ml-2">
                  <Crown className="h-3 w-3 mr-1" />
                  Premium
                </Badge>
              )}
            </CardTitle>
            {!isEditing && (
              <Button variant="outline" onClick={() => setIsEditing(true)}>
                <Edit className="h-4 w-4 mr-2" />
                Edit Profile
              </Button>
            )}
          </CardHeader>
          <CardContent className="space-y-4">
            {error && (
              <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 text-red-600 dark:text-red-400 px-4 py-3 rounded-md text-sm">
                {error}
              </div>
            )}

            {success && (
              <div className="bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800 text-green-600 dark:text-green-400 px-4 py-3 rounded-md text-sm">
                {success}
              </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="fullName" className="dark:text-white">
                  Full Name
                </Label>
                {isEditing ? (
                  <Input
                    id="fullName"
                    value={profileData.fullName}
                    onChange={(e) => setProfileData((prev) => ({ ...prev, fullName: e.target.value }))}
                    placeholder="Enter your full name"
                    className="dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                  />
                ) : (
                  <div className="p-3 bg-gray-50 dark:bg-gray-800 rounded-md text-gray-900 dark:text-white">
                    {userData.fullName || "Not set"}
                  </div>
                )}
              </div>

              <div className="space-y-2">
                <Label htmlFor="username" className="dark:text-white">
                  Username
                </Label>
                {isEditing ? (
                  <Input
                    id="username"
                    value={profileData.username}
                    onChange={(e) => setProfileData((prev) => ({ ...prev, username: e.target.value }))}
                    placeholder="Enter your username"
                    className="dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                  />
                ) : (
                  <div className="p-3 bg-gray-50 dark:bg-gray-800 rounded-md text-gray-900 dark:text-white">
                    {userData.username || "Not set"}
                  </div>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="email" className="dark:text-white">
                Email Address
              </Label>
              <div className="p-3 bg-gray-50 dark:bg-gray-800 rounded-md flex items-center gap-2">
                <Mail className="h-4 w-4 text-gray-400" />
                <span className="text-gray-900 dark:text-white">{userData.email}</span>
                <span className="text-xs text-gray-500 ml-auto">(Cannot be changed)</span>
              </div>
            </div>

            {isEditing && (
              <div className="flex gap-2 pt-4">
                <Button onClick={handleProfileUpdate} disabled={loading}>
                  {loading ? (
                    <>
                      <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                      Saving...
                    </>
                  ) : (
                    <>
                      <Save className="h-4 w-4 mr-2" />
                      Save Changes
                    </>
                  )}
                </Button>
                <Button variant="outline" onClick={handleCancel}>
                  <X className="h-4 w-4 mr-2" />
                  Cancel
                </Button>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Password Change */}
        <Card>
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle className="dark:text-white">Change Password</CardTitle>
            {!isChangingPassword && (
              <Button variant="outline" onClick={() => setIsChangingPassword(true)}>
                Change Password
              </Button>
            )}
          </CardHeader>
          <CardContent>
            {isChangingPassword ? (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="newPassword" className="dark:text-white">
                    New Password
                  </Label>
                  <div className="relative">
                    <Input
                      id="newPassword"
                      type={showPassword ? "text" : "password"}
                      value={passwordData.newPassword}
                      onChange={(e) => setPasswordData((prev) => ({ ...prev, newPassword: e.target.value }))}
                      placeholder="Enter new password"
                      className="dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword(!showPassword)}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                    >
                      {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </button>
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="confirmPassword" className="dark:text-white">
                    Confirm New Password
                  </Label>
                  <div className="relative">
                    <Input
                      id="confirmPassword"
                      type={showConfirmPassword ? "text" : "password"}
                      value={passwordData.confirmPassword}
                      onChange={(e) => setPasswordData((prev) => ({ ...prev, confirmPassword: e.target.value }))}
                      placeholder="Confirm new password"
                      className="dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                    />
                    <button
                      type="button"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
                    >
                      {showConfirmPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </button>
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="flex gap-2">
                    <Button onClick={handlePasswordChange} disabled={loading}>
                      {loading ? (
                        <>
                          <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                          Changing...
                        </>
                      ) : (
                        "Change Password"
                      )}
                    </Button>
                    <Button variant="outline" onClick={handleCancel}>
                      Cancel
                    </Button>
                  </div>

                  <div className="border-t pt-4">
                    <div className="flex items-start gap-3 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
                      <AlertTriangle className="h-5 w-5 text-blue-600 dark:text-blue-400 mt-0.5 flex-shrink-0" />
                      <div className="flex-1">
                        <p className="text-sm font-medium text-blue-800 dark:text-blue-200">Alternative Method</p>
                        <p className="text-sm text-blue-700 dark:text-blue-300 mt-1">
                          If you're having trouble changing your password, you can receive a password reset email instead.
                        </p>
                        <Button 
                          variant="outline" 
                          size="sm" 
                          onClick={handlePasswordReset}
                          disabled={loading}
                          className="mt-2 border-blue-300 text-blue-700 hover:bg-blue-100 dark:border-blue-600 dark:text-blue-300 dark:hover:bg-blue-900/30"
                        >
                          Send Password Reset Email
                        </Button>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <p className="text-gray-600 dark:text-gray-400">
                Click "Change Password" to update your account password.
              </p>
            )}
          </CardContent>
        </Card>

        {/* Account Information */}
        <Card>
          <CardHeader>
            <CardTitle className="dark:text-white">Account Information</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex justify-between">
              <span className="text-gray-600 dark:text-gray-400">Account Created</span>
              <span className="font-medium text-gray-900 dark:text-white">
                {userData.createdAt ? new Date(userData.createdAt).toLocaleDateString() : "N/A"}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-600 dark:text-gray-400">Last Updated</span>
              <span className="font-medium text-gray-900 dark:text-white">
                {userData.updatedAt ? new Date(userData.updatedAt).toLocaleDateString() : "N/A"}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-600 dark:text-gray-400">Account Type</span>
              <div className="flex items-center gap-2">
                <span className="font-medium text-gray-900 dark:text-white">
                  {userData.isPremium ? "Premium Account" : "Free Account"}
                </span>
                {userData.isPremium && (
                  <Badge className="bg-gradient-to-r from-purple-500 to-blue-500 text-white">
                    <Crown className="h-3 w-3 mr-1" />
                    Premium
                  </Badge>
                )}
              </div>
            </div>
            {userData.isPremium && userData.premiumExpiresAt && (
              <div className="flex justify-between">
                <span className="text-gray-600 dark:text-gray-400">Premium Expires</span>
                <span className="font-medium text-gray-900 dark:text-white">
                  {new Date(userData.premiumExpiresAt).toLocaleDateString()}
                </span>
              </div>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  )
}

